  'Всё нынешнее содержимое хранилища будет заменено содержимым копии — вместе с заметками, досками и чеками. Перед заменой нынешнее состояние тоже сохранится копией «перед возвратом», так что передумать можно тем же способом. Оформление и финансовый профиль останутся нынешними.': 'Сав садашњи садржај складишта биће замењен садржајем копије — заједно са белешкама, таблама и рачунима. Пре замене садашње стање ће се такође сачувати као копија „пре враћања“, па се можете предомислити на исти начин. Изглед и финансијски профил остају садашњи.',
