  'Операции этой категории останутся без категории, а её подкатегории станут главными. Сразу после удаления всё можно вернуть кнопкой «Отменить».': 'Трансакције ове категорије остаће без категорије, а њене поткатегорије постаће главне. Одмах после брисања све се може вратити дугметом „Опозови“.',
