  'Подписка, аренда, техника, отпуск. Прогноз по темпу считает такие траты один раз, а не растягивает на весь месяц.': 'Претплата, кирија, техника, одмор. Прогноза по темпу рачуна такве трошкове једном, а не развлачи их на цео месец.',
  'Откуда доход': 'Одакле приход',
  'Доход с капитала, а не с труда': 'Приход од капитала, а не од рада',
  '{0}Дивиденды, купоны, аренда, проценты по вкладу. Отличить это от заработка сама программа не может: в операции видно только сумму, счёт и статью. Отметка ставится один раз и распространяется на всю историю по статье.': '{0}Дивиденде, купони, кирија, камата на депозит. Програм сам не може да то разликује од зараде: у трансакцији се види само износ, рачун и ставка. Ознака се ставља једном и важи за целу историју ставке.',
