  'Выберите основу: от неё тема возьмёт устройство — шапку, кнопки, шрифт, светлая она или тёмная. Цвета потом поменяете как угодно.': 'Изаберите основу: од ње тема узима уређење — заглавље, дугмад, фонт, да ли је светла или тамна. Боје после мењајте како год желите.',
