  'Программа раз в сутки тихо смотрит, нет ли новой версии, и ничего не скачивает без вашего согласия. Объявление об обновлении подписано ключом, который есть только у автора программы: подменённый файл не установится, даже если взломают сам сайт. Скачанное дополнительно сверяется по размеру и контрольной сумме.': 'Програм једном дневно тихо проверава да ли има нове верзије и ништа не преузима без вашег пристанка. Најава ажурирања је потписана кључем који има само аутор програма: подметнута датотека се неће инсталирати, чак и ако провале сам сајт. Преузето се додатно проверава по величини и контролном збиру.',
