  'Ничего не движется: цифры меняются мгновенно, списки перерисовываются сразу.': 'Ништа се не помера: бројеви се мењају тренутно, листе се одмах поново исцртавају.',
  'Умеренные': 'Умерене',
  'Короткие переходы, которые не отвлекают при вводе операций. Без украшений.': 'Кратки прелази који не ометају при уносу трансакција. Без украса.',
  'Перекат цифр, пружины, плавная перестановка списков и декоративные эффекты.': 'Превртање бројева, опруге, глатко премештање листа и украсни ефекти.',
  'Анимации': 'Анимације',
  'Windows сейчас просит уменьшить движение — у вас выключены «Эффекты анимации» (Параметры → Специальные возможности → Визуальные эффекты).{0}': 'Windows сада тражи смањено кретање — искључени су вам „Ефекти анимације“ (Поставке → Приступачност → Визуелни ефекти).{0}',
  ' При режиме «как в системе» это значит, что анимаций не будет. Выберите «Полные», если хотите их видеть в программе несмотря на системную настройку.': ' У режиму „као у систему“ то значи да анимација неће бити. Изаберите „Пуне“ ако желите да их видите у програму упркос системском подешавању.',
  ' Явный выбор выше это перебивает, так что в программе анимации работают.': ' Изричит избор изнад то надјачава, па у програму анимације раде.',
