  ' Ваши записи шифруются им прямо здесь, и ключа нет ни у кого, кроме вас, — ни у сервера, ни у автора программы. Забудете пароль — данные пропадут навсегда. Это плата за то, что чужие деньги никто не прочтёт.': ' Ваши записи се њоме шифрују управо овде и кључ нема нико осим вас — ни сервер, ни аутор програма. Заборавите ли лозинку — подаци ће нестати заувек. То је цена тога да туђи новац нико не прочита.',
