  'Суммарно {0}. Это не обязательно ошибка — но такие операции стоит один раз пересмотреть: ': 'Укупно {0}. То није обавезно грешка — али такве трансакције вреди једном прегледати: ',
  'часть из них разовые и не должна попадать в расчёт «обычного месяца», а часть означает, что появилась новая регулярная статья.': 'део њих је једнократан и не треба да улази у рачун „уобичајеног месеца“, а део значи да се појавила нова редовна ставка.',
