  'Открыть бюджет': 'Отвори буџет',
  '{0} крупных категорий живут без лимита': '{0} великих категорија живи без лимита',
  'Пока у категории нет плановой суммы, перерасход в ней невозможно заметить вовремя — он виден только постфактум. ': 'Док категорија нема планирани износ, прекорачење у њој не може се приметити на време — види се тек накнадно. ',
  'Разумная отправная точка — медиана за последние месяцы, округлённая вверх. Кошель может проставить такие лимиты сам.': 'Разумна полазна тачка — медијана последњих месеци, заокружена навише. Кошељ може сам поставити такве лимите.',
