  'Открыть цели': 'Отвори циљеве',
  'Расходы обгоняют доходы: норма сбережений {0}': 'Трошкови престижу приходе: стопа штедње {0}',
  'Норма сбережений {0} против цели {1}': 'Стопа штедње {0} наспрам циља {1}',
  'Средний доход {0}, средний расход {1}, остаётся {2} в месяц. ': 'Просечан приход {0}, просечан трошак {1}, остаје {2} месечно. ',
  'Чтобы выйти на цель, нужно найти {0} в месяц — это {1} текущих расходов. ': 'Да бисте стигли до циља, треба наћи {0} месечно — то је {1} садашњих трошкова. ',
  'Проще всего взять их из необязательных категорий, а не резать всё подряд на равный процент.': 'Најлакше их је узети из необавезних категорија, а не резати све подједнако.',
