  'Подушка закрывает {0} {1} расходов': 'Резерва покрива {0} {1} трошкова',
  'Цель профиля — {0}. Запас есть; излишек сверх {1} логично переложить под процент, иначе инфляция {2} съедает его молча.': 'Циљ профила — {0}. Резерва постоји; вишак изнад {1} логично је ставити под камату, иначе га инфлација од {2} нечујно поједе.',
  'Активы: {0}': 'Имовина: {0}',
  'Подушки хватит на {0} {1}': 'Резерва ће трајати {0} {1}',
  'При среднем расходе {0} до цели в {1} не хватает {2}. ': 'Уз просечан трошак {0} до циља од {1} недостаје {2}. ',
  'При нынешнем свободном остатке {0} в месяц цель закрывается за {1}. ': 'Уз садашњи слободан вишак од {0} месечно циљ се достиже за {1}. ',
  'Свободных денег сейчас нет — сначала нужно вывести месяц в плюс. ': 'Слободног новца сада нема — прво треба месец извести у плус. ',
  'Держать подушку лучше отдельно от текущего счёта, иначе она тратится незаметно.': 'Резерву је боље држати одвојено од текућег рачуна, иначе се неприметно потроши.',
  'Цель: {0}': 'Циљ: {0}',
