  'Риск уйти в минус за год — {0}': 'Ризик одласка у минус за годину — {0}',
  'Из {0} симуляций {1}% заканчиваются отрицательным остатком хотя бы в одном месяце. ': 'Од {0} симулација {1}% се завршава негативним стањем бар у једном месецу. ',
  'Медианный сценарий пробивает ноль в {0}. ': 'Медијански сценарио пробија нулу у {0}. ',
  'Медианный сценарий держится в плюсе, но запас невелик. ': 'Медијански сценарио остаје у плусу, али резерва је мала. ',
  'Это считается по вашей же истории: разброс берётся из фактических отклонений месяц к месяцу, а не из абстрактных процентов.': 'Ово се рачуна по вашој историји: распон се узима из стварних одступања месец за месецом, а не из апстрактних процената.',
  'Остаток сейчас: {0}': 'Стање сада: {0}',
  'Средний результат месяца: {0}': 'Просечан резултат месеца: {0}',
  'Через год (медиана): {0}': 'За годину (медијана): {0}',
  'Раскладка 50/30/20: сейчас {0}/{1}/{2}': 'Расподела 50/30/20: сада {0}/{1}/{2}',
  '«Надо» — {0}, «хочу» — {1}, остаётся {2}. ': '„Потребно“ — {0}, „желим“ — {1}, остаје {2}. ',
  'Необязательные траты превышают ориентир на {0} в месяц. Перенос этой суммы в накопления даёт {1} за год. ': 'Необавезни трошкови премашују оријентир за {0} месечно. Пребацивање тог износа у уштеђевину даје {1} годишње. ',
  'Необязательные траты в пределах ориентира. ': 'Необавезни трошкови су у оквиру оријентира. ',
  'Пропорция условна: при доходе выше среднего доля «надо» естественно ниже, и это нормально.': 'Однос је услован: уз приход изнад просека удео „потребно“ је природно мањи, и то је у реду.',
  'Надо: {0} ({1})': 'Потребно: {0} ({1})',
  'Хочу: {0} ({1})': 'Желим: {0} ({1})',
  'Остаётся: {0} ({1})': 'Остаје: {0} ({1})',
  '{0} дохода даёт один источник — {1}': '{0} прихода даје један извор — {1}',
  'За полгода «{0}» принёс {1} из {2}. ': 'За пола године „{0}“ је донео {1} од {2}. ',
  'Если этот канал остановится, доход упадёт на {0} в месяц, а запаса хватит на {1} {2}. ': 'Ако овај канал стане, приход ће пасти за {0} месечно, а резерва ће трајати {1} {2}. ',
  'Второй источник не обязан быть большим: даже 20–25% дохода из другого канала снимают основную часть риска. ': 'Други извор не мора бити велик: чак 20–25% прихода из другог канала скида главни део ризика. ',
  'Практический ориентир — довести второй канал до {0} в месяц.': 'Практични оријентир — довести други канал до {0} месечно.',
  '{0}: {1}/мес ({2})': '{0}: {1}/мес ({2})',
  'Сценарий: рост дохода на 20%': 'Сценарио: раст прихода за 20%',
  'Доход скачет: разброс {0} от среднего': 'Приход скаче: распон {0} од просека',
  'Средний месяц — {0}, худший за историю — {1}. ': 'Просечан месец — {0}, најгори у историји — {1}. ',
  'Для нестабильного дохода обычный совет «откладывать фиксированную сумму» работает плохо: ': 'За нестабилан приход уобичајени савет „одвајати сталан износ“ лоше функционише: ',
  'надёжнее откладывать процент от каждого поступления и держать отдельный буфер на слабый месяц. ': 'поузданије је одвајати проценат од сваког прилива и држати посебну резерву за слаб месец. ',
  'Буфер, закрывающий провал до среднего расхода, — {0}.': 'Резерва која покрива пад до просечног трошка — {0}.',
  'Даже худший месяц покрывал расходы — буфер уже фактически есть.': 'Чак је и најгори месец покривао трошкове — резерва фактички већ постоји.',
  'Среднее: {0}': 'Просек: {0}',
