  'Раньше сюда уходило около {0} в месяц, последняя операция — {1}. ': 'Раније је овамо одлазило око {0} месечно, последња трансакција — {1}. ',
  'При этом лимит {0} всё ещё занимает место в бюджете и портит раскладку: бюджет считает эти деньги занятыми. ': 'Притом лимит од {0} и даље заузима место у буџету и квари расподелу: буџет сматра тај новац заузетим. ',
  'Освободившиеся {0} в месяц никуда не делись — если они не переехали в другую категорию, значит просто растворились в общих тратах. ': 'Ослобођених {0} месечно нису нестали — ако нису прешли у другу категорију, значи да су се просто растопили у општим трошковима. ',
  'Либо категорию пора архивировать, либо траты по ней перестали попадать в учёт.': 'Или је категорију време архивирати, или трошкови по њој више не улазе у евиденцију.',
