  'Это {0} всех ваших расходных операций и примерно {1} {2} в неделю ': 'То је {0} свих ваших расходних трансакција и отприлике {1} {2} недељно ',
  'по {0}. Деньги здесь небольшие, а вот решений — больше, чем в любой другой категории: ': 'по {0}. Новац је овде мали, али одлука — више него у било којој другој категорији: ',
  'каждая такая покупка это ещё один повод достать карту. Обычно достаточно собрать их в один заход раз в неделю — ': 'свака таква куповина је још један повод да извадите картицу. Обично је довољно скупити их у један одлазак недељно — ',
  'сумма меняется мало, а число мелких решений падает в разы.': 'износ се мало мења, а број ситних одлука пада вишеструко.',
