  'Совпали день, сумма, категория и комментарий. Так выглядит двойное списание банка, повторный импорт выписки ': 'Поклопили су се дан, износ, категорија и коментар. Тако изгледа двоструко задужење банке, поновни увоз извода ',
  'или дважды занесённая вручную операция. Иногда это правда — два одинаковых кофе бывают, — но проверить стоит: ': 'или двапут ручно унета трансакција. Понекад је то истина — две исте кафе се дешавају — али вреди проверити: ',
  'лишние записи завышают и норму месяца, и прогноз, а банковский дубль ещё и возвращают по заявлению.': 'сувишни записи увећавају и месечну меру и прогнозу, а банкарски дупликат се враћа и по захтеву.',
