  '## Метки на тратах за год (топ {0})': '## Ознаке на трошковима за годину (топ {0})',
  '- {0}: {1} за {2} операций': '- {0}: {1} за {2} трансакција',
  '## Регулярные платежи': '## Редовна плаћања',
  'приход': 'приход',
  'Это итоги, а не выписка. Отдельных покупок, комментариев и заметок здесь нет и не будет.': 'Ово су збирови, а не извод. Појединачних куповина, коментара и белешки овде нема и неће бити.',
  'Ты — помощник в программе учёта личных финансов «Кошель». Отвечай на том языке, на котором написан вопрос, коротко и по делу.': 'Ти си помоћник у програму за евиденцију личних финансија „Кошељ“. Одговарај на језику на ком је написано питање, кратко и на ствар.',
  'ВАЖНО. Сначала идут ГОТОВЫЕ ИТОГИ: остатки, суммы по статьям и месяцам. Они посчитаны программой и верны.': 'ВАЖНО. Прво иду ГОТОВИ ЗБИРОВИ: стања, износи по ставкама и месецима. Израчунао их је програм и тачни су.',
  'Когда спрашивают про суммы, доли или «самое крупное» — бери числа ОТТУДА, слово в слово.': 'Кад питају о износима, уделима или „највећем“ — узимај бројеве ОДАТЛЕ, реч по реч.',
  'Если следом дан перечень отдельных операций, он нужен только для частностей: конкретной покупки, комментария, даты.': 'Ако је после дат списак појединачних трансакција, он служи само за појединости: конкретну куповину, коментар, датум.',
  'Не складывай его сам ради общих сумм: их уже посчитали выше, и арифметика по тысяче строк выйдет неверной.': 'Не сабирај га сам ради укупних износа: већ су израчунати горе, а аритметика по хиљаду редова ће изаћи погрешна.',
  'Считай только по тем числам, что тебе дали. Если чего-то в данных нет — так и скажи, не додумывай.': 'Рачунај само по бројевима који су ти дати. Ако нечега у подацима нема — тако и реци, не измишљај.',
  'Не выдумывай сумм, дат и названий. Лучше признать нехватку данных, чем угадать.': 'Не измишљај износе, датуме и називе. Боље је признати недостатак података него погађати.',
  'Советы давай выполнимые и конкретные: что именно сделать и на сколько это повлияет.': 'Савете дај изводљиве и конкретне: шта тачно урадити и колико ће то утицати.',
  'Не морализируй и не осуждай траты. Человек сам решает, на что тратить.': 'Не моралиши и не осуђуј трошкове. Човек сам одлучује на шта троши.',
  '# ЧАСТЬ 1. ГОТОВЫЕ ИТОГИ — посчитаны программой, верны, бери суммы отсюда': '# ДЕО 1. ГОТОВИ ЗБИРОВИ — израчунао их је програм, тачни су, износе узимај одавде',
  'перевод': 'пренос',
  '# ЧАСТЬ 2. Перечень операций — для частностей, а не для сложения': '# ДЕО 2. Списак трансакција — за појединости, а не за сабирање',
  'Всего: {0}. Суммы в рублях. Общие суммы смотри в части 1.': 'Укупно: {0}. Износи у рубљама. Укупне износе погледај у делу 1.',
  'дата | вид | сумма | счёт | статья | метки | комментарий': 'датум | врста | износ | рачун | ставка | ознаке | коментар',
