  'Файл не читается как тема — это не JSON.': 'Датотека се не чита као тема — није JSON.',
  'Это не файл темы Кошеля.': 'Ово није датотека теме Кошеља.',
  'Нужна картинка: PNG, JPG, WebP, GIF или SVG.': 'Потребна је слика: PNG, JPG, WebP, GIF или SVG.',
  'Картинка больше 8 МБ — для значка это слишком. Уменьшите её и попробуйте снова.': 'Слика је већа од 8 МБ — за иконицу је то превише. Смањите је и покушајте поново.',
  'Файл не прочитался.': 'Датотека се није прочитала.',
  'Картинка не открылась — возможно, файл повреждён.': 'Слика се није отворила — можда је датотека оштећена.',
  'Не удалось подготовить картинку.': 'Припрема слике није успела.',
  'Имперская': 'Царска',
  'Чёрное съ золотомъ и шрифтъ съ засѣчками — въ духѣ казённой бумаги. Чины, ордена и грамота смотрятся въ ней такъ, какъ задумано.': 'Црно са златом и фонт са серифима — у духу државних аката. Чинови, ордени и повеља изгледају у њој онако како је замишљено.',
  'Обсидиан': 'Обсидијан',
  'Спокойная тёмная в духе Obsidian: мягкие серые, умеренные скругления, ничего лишнего.': 'Мирна тамна у духу Obsidian-а: меке сиве, умерена заобљења, ништа сувишно.',
  'Графит': 'Графит',
  'Строгая и плотная: почти чёрный фон, тонкие границы, минимум теней и скруглений.': 'Строга и збијена: скоро црна позадина, танке ивице, минимум сенки и заобљења.',
  'Стекло': 'Стакло',
  'Полупрозрачные панели с размытием поверх глубокого градиента. Красиво, но чуть тяжелее для видеокарты.': 'Полупровидни панели са замућењем преко дубоког градијента. Лепо, али мало теже за графичку картицу.',
  'Неон': 'Неон',
  'Максимальный контраст и свечение акцента. Острые углы, чёткие границы, цифры видно издалека.': 'Максималан контраст и сјај нагласка. Оштри углови, јасне ивице, бројеви се виде издалека.',
  'Мята': 'Нана',
  'Светлая зелёная — как в мобильных трекерах расходов, с которых списан дашборд.': 'Светла зелена — као у мобилним евиденцијама трошкова по којима је прављена контролна табла.',
  'Тёплая бумага': 'Топли папир',
  'Кремовый фон, тёплые серые, крупные скругления и воздух. Мягче для глаз при долгой работе.': 'Крем позадина, топле сиве, крупна заобљења и простор. Блажа за очи при дугом раду.',
  'Знамя': 'Застава',
  'Чёрное, жёлтое, белое — флажные цвета, а не тусклое золото. Мягкие скругления и тёплая подсветка по углам, как у «Обсидиана». Зелёного нет: приход помечен жёлтым.': 'Црно, жуто, бело — заставне боје, а не мутно злато. Мека заобљења и топло осветљење по угловима, као у „Обсидијану“. Зелене нема: приход је означен жутом.',
  'Знамя дневное': 'Застава дневна',
  'То же трёхцветие при свете: белое поле, чёрные буквы, жёлтые заливки и кнопки. Жёлтым по белому не пишут — он там пропадает, — поэтому здесь он работает фоном, а не чернилами.': 'Иста тробојка на светлу: бело поље, црна слова, жуте испуне и дугмад. Жутом по белом се не пише — тамо нестаје — зато овде ради као позадина, а не као мастило.',
  'Триколор': 'Тробојка',
  'Белое поле, синий акцент, красный на расходах — флаг складывается сам, без нарисованного флага. Зелёного нет: приход синий.': 'Бело поље, плави нагласак, црвено на трошковима — застава се слаже сама, без нацртане заставе. Зелене нема: приход је плав.',
  'Триколор ночной': 'Тробојка ноћна',
  'Тот же флаг по тёмно-синему. Красный и синий на чистом чёрном отдают неоном, а по синеватой темноте ложатся спокойно.': 'Иста застава по тамноплавом. Црвена и плава на чистој црној делују неонски, а по плавичастој тами леже мирно.',
  'Пикми': 'Пикми',
  'Молочно-розовое с лиловым, круглые углы и бант в шапке. Пастель взята из выверенных палитр, а не подобрана на глаз: розовый текст на белом легко превратить в кашу.': 'Млечно-ружичаста са лила, округли углови и машна у заглављу. Пастел је узет из проверених палета, а не одабран напамет: ружичасти текст на белом лако се претвори у кашу.',
  'Пикми ночная': 'Пикми ноћна',
  'Та же розовая с лиловым, но по сливовой темноте. Вечером глазам легче, и розовый на тёмном звучит резче.': 'Иста ружичаста са лила, али по шљивастој тами. Увече је очима лакше, а ружичаста на тамном звучи оштрије.',
  'Доход и расход': 'Приход и трошак',
  'Сколько пришло и ушло за период доски': 'Колико је стигло и отишло за период табле',
