  'Прогресс': 'Напредак',
  'Свой виджет': 'Свој виџет',
  'Виджета нет ни в библиотеке, ни на доске. Удалите карточку или соберите его заново.': 'Виџета нема ни у библиотеци ни на табли. Обришите картицу или га поново саставите.',
  'этот год': 'ова година',
  'всё время': 'све време',
  'Из библиотеки: правка видна на всех досках': 'Из библиотеке: измена се види на свим таблама',
  'Ошибка в формуле: {0}': 'Грешка у формули: {0}',
  'Раскладывать нечего: у этого показателя нет частей. Выберите вид «Число» или «Линия».': 'Нема шта да се расподели: овај показатељ нема делове. Изаберите приказ „Број“ или „Линија“.',
  'Для прогресса нужна цель: выберите цель в «Что считать» или впишите сумму в конструкторе.': 'За напредак је потребан циљ: изаберите циљ у „Шта рачунати“ или упишите износ у конструктору.',
  'Осталось: {0}': 'Остало: {0}',
  'Чистый поток': 'Чист ток',
  'Сумма по категории': 'Износ по категорији',
  'Остаток счёта': 'Стање рачуна',
  'Число операций': 'Број трансакција',
  'Как у доски': 'Као код табле',
  'Подпись': 'Потпис',
