  'Сейчас считает формула ниже': 'Сада рачуна формула испод',
  'Категория или подкатегория': 'Категорија или поткатегорија',
  'Формула — по желанию': 'Формула — по жељи',
  'Сложить, вычесть, умножить и разделить показатели; имена — как в подсказках ниже, с уточнением через двоеточие. Деньги в формуле — в рублях.': 'Сабирајте, одузимајте, множите и делите показатеље; имена — као у подсказкама испод, са прецизирањем преко две тачке. Новац у формули — у целим јединицама.',
  'например: {0}': 'на пример: {0}',
  'Еда': 'Храна',
  'Писать как': 'Писати као',
  'Фильтры': 'Филтери',
  'Личные': 'Лични',
  'Проектные': 'Пројектни',
  'Убрать из фильтра': 'Уклони из филтера',
  'все': 'сви',
