  'Деньги лежат у вас, но не ваши: в доход, чистый капитал, прогноз и награды не входят.': 'Новац је код вас, али није ваш: не улази у приход, нето вредност, прогнозу и награде.',
  ' В архиве: {0}': ' У архиви: {0}',
  'Удалить счёт «{0}»?': 'Обрисати рачун „{0}“?',
  'Операции по этому счёту останутся в истории, но повиснут без привязки. Обычно правильнее оставить счёт и просто перестать им пользоваться. Сразу после удаления его можно вернуть кнопкой «Отменить».': 'Трансакције по овом рачуну остаће у историји, али без везе. Обично је исправније оставити рачун и само престати да га користите. Одмах после брисања може се вратити дугметом „Опозови“.',
