  'Деньги пришли на счёт или траты идут с самой кредитной карты — они уже расходы, поэтому из платежа в расходы идут только проценты.': 'Новац је стигао на рачун или трошкови иду са саме кредитне картице — они су већ трошкови, зато из рате у трошкове иде само камата.',
