  'Счёт под проект — деньги не мои': 'Рачун за пројекат — новац није мој',
  'Аванс за работу, сбор на издание, бюджет кампании. Приходы и траты по такому счёту не считаются вашим доходом и расходом, остаток не входит в чистый капитал, прогноз и награды. Счёт остаётся видимым, и по нему считается своя сводка на главной. Перевод между проектным и личным счётом сохраняется — но доходом он не становится: свой гонорар заведите отдельным приходом.': 'Аванс за посао, прикупљање за издање, буџет кампање. Приходи и трошкови по таквом рачуну не рачунају се као ваш приход и трошак, стање не улази у нето вредност, прогнозу и награде. Рачун остаје видљив и за њега се рачуна посебан преглед на почетној. Пренос између пројектног и личног рачуна се чува — али не постаје приход: свој хонорар унесите као засебан приход.',
