  'Как это считается': 'Како се ово рачуна',
  'Никаких обращений в интернет: движок берёт ваши операции, строит по каждой категории устойчивую норму (медиана последних месяцев), тренд и разброс, сверяет текущий темп с этой нормой и проверяет два десятка правил — от забытых подписок до концентрации дохода в одном источнике. Цифры в советах — это ваши же деньги, пересчитанные в месячный и годовой масштаб; именно в нём мелкие регулярные траты становятся заметными.': 'Никаквих захтева ка интернету: механизам узима ваше трансакције, гради за сваку категорију стабилну меру (медијана последњих месеци), тренд и распон, пореди тренутни темпо са том мером и проверава двадесетак правила — од заборављених претплата до концентрације прихода у једном извору. Бројеви у саветима — то је ваш сопствени новац, прерачунат на месечну и годишњу размеру; управо у њој ситни редовни трошкови постају уочљиви.',
