  '50/30/20 — не закон, а быстрый способ увидеть перекос. Если «надо» стабильно выше 60%, бюджет негибкий: в плохой месяц резать будет нечего.': '50/30/20 — није закон, него брз начин да се види искривљеност. Ако је „потребно“ стално изнад 60%, буџет није флексибилан: у лошем месецу неће бити шта да се сече.',
