  'Что здесь создать?': 'Шта овде направити?',
  'Доска, на которой рядом живут заметки, счета, категории и цели. Связи между ними — стрелки: если соединить счёт с категорией, толщина покажет оборот между ними.': 'Табла на којој једни поред других живе белешке, рачуни, категорије и циљеви. Везе између њих су стрелице: ако спојите рачун са категоријом, дебљина ће показати промет између њих.',
  ' Создать первую доску': ' Направи прву таблу',
  'Связь': 'Веза',
  'Потяните, чтобы перецепить связь': 'Повуците да прикачите везу на друго место',
