  'Потяните, чтобы изменить размер': 'Повуците да промените величину',
  'Доска пустая': 'Табла је празна',
  'Карточка — двойной щелчок по доске, клавиша T или полка внизу. С полки же кладут задачу, заметку, счёт, категорию и цель. Чтобы связать две карточки, потяните за кружок на краю — если отпустить на пустом месте, программа предложит, что там создать.': 'Картица — двоструки клик по табли, тастер T или полица доле. Са полице се стављају и задатак, белешка, рачун, категорија и циљ. Да повежете две картице, повуците кружић на ивици — ако га пустите на празном месту, програм ће понудити шта да се ту направи.',
  'подпись': 'потпис',
