  'Для всех досок. Линии, которые вы не меняли по отдельности, сразу примут этот вид; свой вид связи — щелчок по ней → «Вид линии».': 'За све табле. Линије које нисте мењали појединачно одмах ће добити овај изглед; изглед једне везе — клик на њу → „Изглед линије“.',
