  'Наведите на линию или карточку — по её связям побежит штрих по стрелке. В покое ничего не движется.': 'Пређите мишем преко линије или картице — по њеним везама потрчаће потез у смеру стрелице. У мировању се ништа не помера.',
  'Анимации сейчас выключены — в настройках или в системе, — поэтому связи только подсвечиваются.': 'Анимације су сада искључене — у подешавањима или у систему — зато се везе само осветљавају.',
