  'Действует на {0}{1}: расходы {2}, пополнения {3}. Кнопки независимы, переводы между счетами не трогаются.': 'Важи за {0}{1}: трошкови {2}, уплате {3}. Дугмад су независна, преноси између рачуна се не дирају.',
