  'Как есть': 'Као сада',
  'сейчас': 'сада',
  'Тренд по вашей истории плюс известные регулярные платежи. Текущий месяц учтён по прожитой части: деньги этого месяца считаются, но растянуть их на полный месяц программа не берётся. Коридор — {0}{1}симуляций на фактическом разбросе ваших месяцев.{2}': 'Тренд по вашој историји плус позната редовна плаћања. Текући месец је урачунат по протеклом делу: новац овог месеца се рачуна, али програм не развлачи га на цео месец. Коридор — {0}{1}симулација на стварном распону ваших месеци.{2}',
  '{0}Показан один счёт, поэтому переводы на другие ваши счета считаются его расходом, а пополнения с них — приходом. На «всех счетах» они по-прежнему не учитываются: там перекладывание денег из кармана в карман итог не меняет.': '{0}Приказан је један рачун, зато се преноси на ваше друге рачуне рачунају као његов трошак, а уплате са њих — као приход. На „свим рачунима“ они се и даље не урачунавају: пребацивање новца из џепа у џеп не мења резултат.',
