  ' Что это даёт': ' Шта то даје',
  'Подвигайте ползунки слева — здесь появится разница между сценарием и текущим положением дел: сколько это даёт в месяц, в год и как сдвигает точку риска.': 'Померајте клизаче лево — овде ће се појавити разлика између сценарија и садашњег стања: колико то даје месечно, годишње и како помера тачку ризика.',
