  'Сохранённый сценарий можно открыть одним кликом и положить карточкой на канвас, чтобы сравнивать варианты рядом.': 'Сачувани сценарио може се отворити једним кликом и ставити као картица на платно, да се варијанте пореде једна поред друге.',
  'Свободно в месяц {0} · цели требуют {1}{2}': 'Слободно месечно {0} · циљеви траже {1}{2}',
  ' · не хватает {0}': ' · недостаје {0}',
  ' Новая цель': ' Нови циљ',
  'Все цели одновременно не тянутся': 'Сви циљеви истовремено се не могу подићи',
  'Свободных денег {0} в месяц, а цели требуют {1}. Двигать всё понемногу — худший вариант: не закроется ни одна. Оставьте активной цель с ближайшим сроком, остальные поставьте на паузу и вернитесь к ним после.': 'Слободног новца {0} месечно, а циљеви траже {1}. Померати све помало — најгора варијанта: неће се затворити ниједан. Оставите активан циљ са најближим роком, остале паузирајте и вратите им се после.',
  'закрыта': 'затворен',
  'до {0}': 'до {0}',
