  'При текущем темпе': 'По тренутном темпу',
  'закроется {0}': 'биће затворен {0}',
  'Чтобы уложиться в срок, нужно {0} в месяц — это больше свободных {1}. Реалистичные варианты: сдвинуть срок на {2}, снизить цель до {3} или найти {4} в месяц в расходах.': 'Да бисте стигли на време, треба {0} месечно — то је више од слободних {1}. Реалне варијанте: померити рок за {2}, смањити циљ на {3} или наћи {4} месечно у трошковима.',
  'Пополнить на {0}': 'Допуни за {0}',
  'Пополнить': 'Допуни',
  'Отметить закрытой': 'Означи као затворен',
  'Целей пока нет. Первая разумная цель — подушка на 3–6 месяцев расходов.': 'Циљева још нема. Први разуман циљ — резерва од 3–6 месеци трошкова.',
  'Введите название цели': 'Унесите назив циља',
  'Укажите, сколько нужно заработать': 'Наведите колико треба зарадити',
  'Укажите, сколько нужно собрать': 'Наведите колико треба скупити',
  'Цель «{0}» пополнена на {1}': 'Циљ „{0}“ је допуњен за {1}',
  'Пополнить цель «{0}»': 'Допуни циљ „{0}“',
  'Эта цель — счёт «{0}»: сколько на нём лежит, столько и накоплено. Поэтому деньги переводятся на него с другого счёта, иначе цифры цели и счёта разойдутся.': 'Овај циљ је рачун „{0}“: колико на њему има, толико је и уштеђено. Зато се новац преноси на њега са другог рачуна, иначе ће се бројеви циља и рачуна разићи.',
  'Откуда': 'Одакле',
  'Другого счёта нет — переводить неоткуда.': 'Другог рачуна нема — нема одакле да се пренесе.',
