  'Запишите доходы и расходы — схема покажет, откуда пришли деньги, через какие счета прошли и на что ушли.': 'Запишите приходе и трошкове — шема ће показати одакле је новац дошао, кроз које рачуне је прошао и на шта је отишао.',
