  'Потрачено сверх пришедшего за период — из денег, что уже лежали на счетах.': 'Потрошено изнад прилива за период — из новца који је већ био на рачунима.',
  'Потрачено в долг — с кредитной карты или в счёт долга.': 'Потрошено на дуг — са кредитне картице или на рачун дуга.',
  'Пришло, но не потрачено — осталось на счетах.': 'Стигло, али није потрошено — остало је на рачунима.',
  'Ушло на погашение кредитов и долгов.': 'Отишло на отплату кредита и дугова.',
  'Наведите на ленту или статью — увидите путь денег. Щелчок по главной категории раскрывает подкатегории, по остальному — открывает операции.': 'Пређите мишем преко траке или ставке — видећете путању новца. Клик на главну категорију отвара поткатегорије, на остало — отвара трансакције.',
  'подкатегорий: {0}': 'поткатегорија: {0}',
  'вместе с подкатегориями': 'заједно са поткатегоријама',
