  ' Вписать': ' Уклопи',
  'Медленно вращать граф, пока его не трогают': 'Полако окретати граф док га не дирају',
  ' Вращается': ' Окреће се',
  ' Вращать': ' Окрећи',
  'Тяните фон — повернуть, с Shift или правой кнопкой — сдвинуть. Колесо — масштаб. Щелчок по узлу — подробности, двойной — открыть раздел.': 'Вуците позадину — окрените, са Shift или десним тастером — померите. Точкић — размера. Клик на чвор — детаљи, двоструки — отвори одељак.',
  'Тяните фон — сдвинуть. Колесо — масштаб. Щелчок по узлу — подробности, двойной — открыть раздел.': 'Вуците позадину — померите. Точкић — размера. Клик на чвор — детаљи, двоструки — отвори одељак.',
