  'Импортировано операций: {0}': 'Увезено трансакција: {0}',
  'Импорт выписки': 'Увоз извода',
  'Любой CSV: колонки сопоставляются вручную, категории проставляются по правилам, повторы отлавливаются по дате, сумме и описанию': 'Било који CSV: колоне се упарују ручно, категорије се постављају по правилима, понављања се хватају по датуму, износу и опису',
  ' Выбрать файл': ' Изабери датотеку',
  'Как это работает.': 'Како ово ради.',
  ' Выгрузите операции из банка в CSV и откройте файл здесь. Кошель определит разделитель и кодировку (в том числе windows-1251, в которой приходит большинство российских выписок), попробует угадать колонки с датой, суммой и описанием — а вы поправите, если он ошибся.': ' Извезите трансакције из банке у CSV и отворите датотеку овде. Кошељ ће одредити граничник и кодирање (укључујући windows-1251, у ком стиже већина руских извода), покушаће да погоди колоне са датумом, износом и описом — а ви ћете исправити ако је погрешио.',
  'Дальше по правилам ниже операциям проставятся категории: правило — это просто кусок текста из описания. Например, «пятёрочка» → Продукты. Что не распозналось, останется без категории и будет ждать в разделе «Операции».': 'Затим ће по правилима испод трансакцијама бити постављене категорије: правило је само део текста из описа. На пример, „maxi“ → Намирнице. Оно што није препознато остаће без категорије и чекаће у одељку „Трансакције“.',
