  ' Правила автокатегоризации': ' Правила аутоматске категоризације',
  'Если описание операции содержит указанный текст, категория проставится сама. Регистр не важен, проверка идёт по вхождению подстроки.': 'Ако опис трансакције садржи наведени текст, категорија ће се поставити сама. Велика и мала слова нису важна, провера иде по садржају подниза.',
