  'Удалить заметку': 'Обриши белешку',
  '# Заголовок\n\nТекст, [[ссылка на заметку]], #тег\n\n```kashel\ntype: sum\nkind: expense\nperiod: 1m\n```': '# Наслов\n\nТекст, [[веза ка белешци]], #ознака\n\n```kashel\ntype: sum\nkind: expense\nperiod: 1m\n```',
  ' Ссылки отсюда': ' Везе одавде',
  ' Ссылаются сюда': ' Упућују овде',
