  'среда': 'среда',
  'четвергъ': 'четвртак',
  'пятница': 'петак',
  'суббота': 'субота',
  'Чинъ, ордена и характеристики выводятся изъ вашихъ же записей и пересчитываются всякій разъ заново. Ничего не копится отдѣльно: поправите старую запись — сойдётся и здѣсь.': 'Чин, ордени и особине изводе се из ваших записа и сваки пут се поново прерачунавају. Ништа се не гомила посебно: исправите стари запис — сложиће се и овде.',
  'По какой лѣстницѣ считать чинъ': 'По којој лествици рачунати чин',
  'Пока не заслужено ни одной награды': 'Још није заслужена ниједна награда',
  '{0} · {1}-й уровень изъ 14{2}': '{0} · {1}. ниво од 14{2}',
  '{0} опыта': '{0} искуства',
  '{0} опыта{1}': '{0} искуства{1}',
  ' · выше чина нѣтъ': ' · вишег чина нема',
  ' · до чина «{0}» ещё {1}': ' · до чина „{0}“ још {1}',
  'изъ {0} наградъ': 'од {0} награда',
  ' Характеристики': ' Особине',
  ' Откуда опытъ': ' Одакле искуство',
  'Записей пока нѣтъ': 'Записа још нема',
  'Опытъ за доходъ считается съ затуханіемъ: вдесятеро большая сумма даётъ втрое больше, а не вдесятеро. Иначе одинъ крупный гонораръ обратилъ бы всѣ прочіе мѣсяцы въ шумъ. Опытъ не отнимается никогда.': 'Искуство за приход рачуна се са опадањем: десет пута већи износ даје три пута више, а не десет пута. Иначе би један велики хонорар претворио све остале месеце у шум. Искуство се никад не одузима.',
  ' Серія записей': ' Низ записа',
  '{0} подрядъ': '{0} заредом',
  'лучшая — {0}': 'најбољи — {0}',
  'Пропущенный день закрывается заморозкой: ихъ {0} на мѣсяцъ, осталось{1}': 'Пропуштени дан се покрива замрзавањем: има их {0} месечно, остало{1}',
  '. Третій пропускъ серію рветъ. Сдѣлано это нарочно: серія, которую рушитъ одна забытая суббота, отбиваетъ охоту продолжать вовсе.': '. Трећи пропуст прекида низ. То је урађено намерно: низ који руши једна заборављена субота одбија вољу да се уопште настави.',
  'Выходной': 'Слободан дан',
  'Этотъ день недѣли въ серію не считается': 'Овај дан у недељи се не рачуна у низ',
  'безъ выходного': 'без слободног дана',
  'сегодня записано': 'данас је записано',
  'сегодня записи ещё нѣтъ': 'данас још нема записа',
  ' Заданія мѣсяца': ' Задаци месеца',
  'Три штуки, свои на каждый мѣсяцъ. Нигдѣ не хранятся: и выборъ, и выполненіе выводятся изъ записей — поправите старую, и заданіе сойдётся вмѣстѣ съ ней.': 'Три комада, другачија за сваки месец. Нигде се не чувају: и избор и извршење изводе се из записа — исправите стари и задатак ће се сложити заједно са њим.',
  ' Ордена': ' Ордени',
  'У орденовъ Россійской имперіи были степени — отъ младшей четвёртой къ старшей первой. Здѣсь они и служатъ ступенями награды.': 'Ордени Руске империје имали су степене — од млађег четвртог до старијег првог. Овде служе као ступњеви награде.',
  'Пожаловано {0}': 'Додељено {0}',
  'Пожаловано': 'Додељено',
  'откроется, когда сойдётся': 'отвориће се кад се сложи',
  'Пройдено {0} %': 'Пређено {0} %',
  ' Званія': ' Звања',
  'Даются за характеристику, доросшую до восьмидесяти. Нажмите, чтобы закрѣпить рядомъ съ чиномъ.': 'Дају се за особину која је дорасла до осамдесет. Кликните да закачите поред чина.',
  ' — не заслужено': ' — није заслужено',
  ' Что впереди': ' Шта је напред',
  'Ничего не намѣчено': 'Ништа није заказано',
  'Къ дѣламъ': 'Ка пословима',
  'Къ совѣтамъ': 'Ка саветима',
  ' Лѣстница чиновъ': ' Лествица чинова',
  '{0} {1}{2}{3}. Слѣдующая ближайшая —{4}{5}.': '{0} {1}{2}{3}. Следећа најближа —{4}{5}.',
  'Пожалована|Пожаловано|Пожаловано': 'Додељена|Додељене|Додељено',
