  '{0} изъ {1} наградъ{2}': '{0} од {1} награда{2}',
  ' · ближайшая: {0}': ' · најближа: {0}',
  'Открыть грамоту': 'Отвори повељу',
  ', {0} числа': ', {0}. у месецу',
  'Ежемесячно': 'Месечно',
  'Еженедельно': 'Недељно',
  'Ежегодно': 'Годишње',
  'Ежедневно': 'Дневно',
  'Фиксировано {0} расходов и {1} доходов в месяц · за год это {2} обязательных трат': 'Фиксирано је {0} трошкова и {1} прихода месечно · за годину то је {2} обавезних трошкова',
  ' Похоже, это повторяется': ' Изгледа да се ово понавља',
  'Эти траты вы вносили руками, и они идут ровной суммой через равные промежутки. Регулярное правило поставит их в прогноз точной суммой в нужный месяц, а не размажет по среднему.': 'Ове трошкове сте уносили ручно и иду истим износом у једнаким размацима. Редовно правило ће их ставити у прогнозу тачним износом у прави месец, а не размазати по просеку.',
  '{0}{1} · {2}{3}{4} · последний {5}': '{0}{1} · {2}{3}{4} · последњи {5}',
  'Повторяющийся платёж': 'Плаћање које се понавља',
  'Сделать правилом': 'Учини правилом',
  'Автосоздание операций в предложенном правиле выключено: иначе платёж, который вы и дальше будете вносить руками, посчитается дважды.': 'Аутоматско прављење трансакција у предложеном правилу је искључено: иначе би се плаћање које и даље уносите ручно урачунало двапут.',
  'Периодичность': 'Учесталост',
  'В год': 'Годишње',
  'Операции создаются автоматически': 'Трансакције се праве аутоматски',
  'авто': 'ауто',
  'Приостановить': 'Паузирај',
  'Возобновить': 'Настави',
  'Регулярных платежей нет': 'Редовних плаћања нема',
  'Зачем это нужно прогнозу': 'Зашто је ово потребно прогнози',
  'Регулярные платежи попадают в прогноз как точные суммы, а не как усреднённая статистика. Чем больше обязательных платежей описано здесь, тем точнее прогноз и тем меньше «сюрпризов» в конце месяца. Их суммы при этом исключаются из расчёта переменной части категории, чтобы не считаться дважды.': 'Редовна плаћања улазе у прогнозу као тачни износи, а не као просечна статистика. Што је више обавезних плаћања овде описано, то је прогноза тачнија и мање је „изненађења“ на крају месеца. Њихови износи се притом искључују из рачуна променљивог дела категорије, да се не би рачунали двапут.',
  'Нужны название и сумма': 'Потребни су назив и износ',
  'Выберите категорию — без неё платёж не попадёт в разбор по категориям': 'Изаберите категорију — без ње плаћање неће ући у расподелу по категоријама',
  'Для перевода нужны два разных счёта': 'За пренос су потребна два различита рачуна',
  'Новый регулярный платёж': 'Ново редовно плаћање',
  'Подписка, аренда, зарплата': 'Претплата, кирија, плата',
