  'Свои напоминания: по дате или по событию в ваших деньгах. Приходят, пока окно открыто — фонового режима у программы нет, в автозапуск она себя не прописывает.': 'Ваши подсетници: по датуму или по догађају у вашем новцу. Стижу док је прозор отворен — програм нема позадински режим и не уписује се у аутоматско покретање.',
  ' По дате': ' По датуму',
  ' По событию': ' По догађају',
  'Звук': 'Звук',
  'Условие выполнено прямо сейчас': 'Услов је испуњен управо сада',
  'Напоминаний пока нет': 'Подсетника још нема',
  'Чем «по событию» отличается от «по дате»': 'Чиме се „по догађају“ разликује од „по датуму“',
  '«По дате» — обычный ежедневник: текст и день. Пропущенное не пропадает: если программу неделю не открывали, напоминание дождётся и покажется при следующем запуске. «По событию» — условие, за которым программа следит сама: остаток упал ниже порога, категория вышла за лимит, давно не вносили траты. Каждое напоминание звонит не чаще раза в день, иначе оно превратилось бы в шум и его выключили бы в первый же вечер.': '„По датуму“ — обичан роковник: текст и дан. Пропуштено не нестаје: ако програм недељу дана није отваран, подсетник ће сачекати и појавити се при следећем покретању. „По догађају“ — услов који програм сам прати: стање је пало испод прага, категорија је прешла лимит, дуго нисте уносили трошкове. Сваки подсетник звони не чешће од једном дневно, иначе би се претворио у шум и искључили бисте га већ прве вечери.',
