  'Скрывать баланс': 'Скривај стање',
  'Неделя начинается с': 'Недеља почиње од',
  'Формат даты': 'Формат датума',
  'Свои даты программа перепишет сразу. Встроенный выбор даты берёт язык при запуске, поэтому там формат сменится со следующего открытия.': 'Своје датуме програм ће одмах преписати. Уграђени избор датума узима језик при покретању, зато ће се тамо формат променити од следећег отварања.',
  'Закрывать в трей': 'Затварај у траку',
  '{0}Крестик прячет окно в трей, программа продолжает работать — напоминания и помидор остаются живыми. Свёрнутое окно остаётся на панели задач. Выйти совсем — правой кнопкой по значку в трее.': '{0}Крстић сакрива прозор у траку, програм наставља да ради — подсетници и помодоро остају живи. Умањен прозор остаје на траци задатака. Потпуно изаћи — десним тастером на иконицу у траци.',
  ' Финансовый профиль': ' Финансијски профил',
  'От этих чисел зависят советы: с ними сверяются норма сбережений, размер подушки и выгодность досрочного погашения.': 'Од ових бројева зависе савети: са њима се пореде стопа штедње, величина резерве и исплативост превремене отплате.',
  'Подушка, месяцев расходов': 'Резерва, месеци трошкова',
