  'Больше симуляций — более гладкий коридор, но заметнее задержка при пересчёте': 'Више симулација — глаткији коридор, али приметније кашњење при прерачунавању',
  ' Звуки и уведомления': ' Звукови и обавештења',
  ' Хранилище': ' Складиште',
