  ' Импорт выписки': ' Увоз извода',
  ' Категории из всех иконок': ' Категорије из свих иконица',
  ' Всё одним файлом': ' Све у једној датотеци',
  'Операции, счета, категории, цели, регулярные платежи, сценарии, правила импорта, заметки, канвасы и фото чеков складываются в один файл ': 'Трансакције, рачуни, категорије, циљеви, редовна плаћања, сценарији, правила увоза, белешке, платна и фотографије рачуна пакују се у једну датотеку ',
  '. Его можно унести на другой компьютер или отправить человеку: он откроет файл здесь же и получит ровно то, что видите вы. Внутри обычный JSON — читается блокнотом.': '. Можете је однети на други рачунар или послати некоме: отвориће је овде и добити тачно оно што видите ви. Унутра је обичан JSON — чита се у Notepad-у.',
  ' Сохранить всё в файл': ' Сачувај све у датотеку',
  ' Загрузить из файла': ' Учитај из датотеке',
  'То же самое лежит в меню «Файл» — «Сохранить как…» и «Открыть…». Загрузка заменяет хранилище целиком; прежнее состояние программа перед этим сама кладёт в ': 'Исто стоји у менију „Датотека“ — „Сачувај као…“ и „Отвори…“. Учитавање замењује цело складиште; претходно стање програм пре тога сам ставља у ',
  ' таким же файлом, вернуться можно той же кнопкой.': ' као исту такву датотеку, па се можете вратити истим дугметом.',
  'Файлы .kashel связаны с прежним расположением программы — двойной клик открывает не то.': 'Датотеке .kashel су повезане са претходном локацијом програма — двоструки клик не отвара оно што треба.',
  'Файлы .kashel открываются двойным кликом.': 'Датотеке .kashel се отварају двоструким кликом.',
  'Двойной клик по файлу .kashel пока ничего не открывает.': 'Двоструки клик на датотеку .kashel засад ништа не отвара.',
  'Готово: файлы .kashel открываются Кошелём': 'Готово: датотеке .kashel отвара Кошељ',
  'Не удалось прописать связь': 'Повезивање није успело',
  'Переставить связь на эту программу': 'Повежи са овим програмом',
  'Связать файлы .kashel с Кошелем': 'Повежи датотеке .kashel са Кошељем',
  'Связь снята': 'Веза је уклоњена',
  'Отвязать': 'Одвоји',
  'Связь прописывается только для вашей учётной записи и прав администратора не требует. Если Кошель установлен через установщик, это уже сделано — кнопка нужна, когда программу запускают прямо из папки проекта.': 'Веза се уписује само за ваш кориснички налог и не захтева администраторска права. Ако је Кошељ инсталиран инсталатером, то је већ урађено — дугме је потребно кад се програм покреће директно из фасцикле пројекта.',
  'Внутри папки: ': 'Унутар фасцикле: ',
  ' — счета, категории, цели и настройки;': ' — рачуни, категорије, циљеви и подешавања;',
  ' transactions/ГГГГ-ММ.json': ' transactions/ГГГГ-ММ.json',
  ' — операции по месяцам;': ' — трансакције по месецима;',
  ' — заметки в markdown; ': ' — белешке у markdown-у; ',
  ' — канвасы;': ' — платна;',
  ' — фото чеков. Всё это обычные текстовые файлы: их можно версионировать через git и синхронизировать любым облаком.': ' — фотографије рачуна. Све су то обичне текстуалне датотеке: могу се верзионисати преко git-а и синхронизовати било којим облаком.',
  ' Горячие клавиши': ' Пречице на тастатури',
