  'категорию|категории|категорий': 'категорију|категорије|категорија',
  'Из каждой иконки каталога получится своя категория — с названием, иконкой и цветом. ': 'Од сваке иконице каталога настаће посебна категорија — са називом, иконицом и бојом. ',
  'Сейчас у вас {0}, станет {1}. ': 'Сада имате {0}, биће {1}. ',
  'Списки, бюджет и бублик на дашборде станут заметно длиннее; лишнее удаляется по одной ': 'Листе, буџет и крофна на контролној табли постаће приметно дужи; сувишно се брише једно по једно ',
  'в «Категориях». Уже заведённые категории и их иконки не трогаются.': 'у „Категоријама“. Већ постојеће категорије и њихове иконице се не дирају.',
