  'Хранилище вернётся к состоянию только что установленной программы: исчезнут ': 'Складиште ће се вратити у стање управо инсталираног програма: нестаће ',
  '{0} операций, {1} счетов вместе с кредитами и долгами, ': '{0} трансакција, {1} рачуна заједно са кредитима и дуговима, ',
  '{0} категорий, {1} целей, {2} регулярных платежей, ': '{0} категорија, {1} циљева, {2} редовних плаћања, ',
  'а также все заметки и канвасы. Настройки и путь к хранилищу сохранятся. ': 'а такође све белешке и платна. Подешавања и путања до складишта ће се сачувати. ',
  'Перед очисткой программа сделает резервную копию — вернуть её можно в разделе «Резервные копии» ниже.': 'Пре чишћења програм ће направити резервну копију — можете је вратити у одељку „Резервне копије“ испод.',
  'Отменить нельзя — если данные нужны, сначала сохраните их кнопкой «Сохранить всё в файл» выше.': 'Не може се опозвати — ако су вам подаци потребни, прво их сачувајте дугметом „Сачувај све у датотеку“ изнад.',
  ' Новая задача': ' Нови задатак',
