  'Отпустите здесь': 'Пустите овде',
  'Как задача попадает в четверть': 'Како задатак доспева у четвртину',
  '«Срочно» программа считает сама: срок сегодня, завтра или уже прошёл. «Важно» — важность задачи: средняя и выше. Высокая важность (красная) сразу ставит задачу в «Срочно и важно». Задачу можно перетащить мышкой в любую четверть — там она и останется, пока вы не поменяете ей срок или важность.': '„Хитно“ програм рачуна сам: рок је данас, сутра или је већ прошао. „Важно“ — важност задатка: средња и виша. Висока важност (црвена) одмах ставља задатак у „Хитно и важно“. Задатак се може превући мишем у било коју четвртину — тамо ће и остати док му не промените рок или важност.',
