  'Работа, мин': 'Рад, мин',
  'Перерыв, мин': 'Пауза, мин',
  'Отсчёт идёт по часам, а не по тикам, поэтому не отстаёт, пока вы смотрите другие разделы. Таймер продолжает идти при переключении вкладок и в трее, а о конце отрезка скажет и уведомление Windows.': 'Одбројавање иде по сату, а не по откуцајима, зато не заостаје док гледате друге одељке. Тајмер наставља да тече при промени картица и у траци, а о крају деонице јавиће и обавештење Windows-а.',
  'Звуки помидора': 'Звукови помодора',
