  '{0}. В матрицу идёт средняя и выше.': '{0}. У матрицу иде средња и виша.',
  'Время': 'Време',
  'Деньги': 'Новац',
  'Задача не про деньги: на неё уходит только время. Сколько — по желанию; оно видно у задачи и в итоге недели и месяца, а в прогноз и платежи задача не идёт.': 'Задатак није о новцу: на њега одлази само време. Колико — по жељи; види се код задатка и у збиру недеље и месеца, а у прогнозу и плаћања задатак не иде.',
  'Сумма необязательна. Если её указать, задача попадёт в прогноз как разовая{0} в месяц своего срока, а закрыть её можно сразу с записью операции. Без срока сумма в прогноз не идёт — некуда её ставить.': 'Износ није обавезан. Ако га наведете, задатак ће ући у прогнозу као једнократни{0} у месецу свог рока, а може се затворити одмах уз запис трансакције. Без рока износ не иде у прогнозу — нема где да се стави.',
