  'Тридцать девять подлинниковъ и ни одного выдуманнаго лица. Здѣсь сказано, кто на каждомъ знакѣ, почему именно онъ и за что даётся награда.': 'Тридесет девет оригинала и ниједно измишљено лице. Овде пише ко је на сваком знаку, зашто баш он и за шта се даје награда.',
