  'Почему онъ.': 'Зашто он.',
  'За что даётся.': 'За шта се даје.',
  'Всѣ изображенія — общественное достояніе: иконы, портреты кисти Рѣпина, Боровиковскаго, Кипренскаго, Перова, Тропинина, Левицкаго, Крейцингера, Доу, Брюллова, Миропольскаго, Веденецкаго, Тюрина, Бажанова, Дункерса, Ботмана, Зубова, парсуны XVII вѣка и губернскіе гербы XVIII столѣтія. Лица не рисованы и не сочинены: въ поле медали посаженъ подлинникъ, вогнанный въ цвѣтъ металла.': 'Све слике су јавно добро: иконе, портрети четкицом Репина, Боровиковског, Кипренског, Перова, Тропињина, Левицког, Кројцингера, Доа, Брјулова, Миропољског, Веденецког, Тјурина, Бажанова, Дункерса, Ботмана, Зубова, парсуне XVII века и губернијски грбови XVIII века. Лица нису цртана ни измишљена: у поље медаље постављен је оригинал, утопљен у боју метала.',
